 1	# gate-functions.sh: the shell functions of the gate's summary and of its ladder comparison.
 2	#
 3	#   gate_summary <log-dir> <out-file> [machine-label]
 4	#                         writes summary.txt: one row per suite from the plain-formatter files under
 5	#                         $FORTRESS_HOME/ProjectFortress/TEST-RESULTS/, then the BUILD and Total time
 6	#                         lines of <log-dir>/{compileAll,testFast,testSystem,testSpecData}.txt, then
 7	#                         "# machine " lines from machine.sh with the label (default "gate")
 8	#   gate_compare <last-landed-summary> <this-summary>
 9	#                         prints the red lines (RED, EMPTY, COUNT DOWN, SUITE GONE), exit 1 if any;
10	#                         the system-<i> rows are one suite split by sorted index, compared by their sum
11	#   last_landed_summary   prints the path of the newest landed summary.txt
12	#   ladder_filter <file>  masks the "Operation took" time of a ladder run's output
13	#   ladder_compare <baseline-dir> <now-dir>
14	#                         one DOWN, UP, NEW, MISSING or STDOUT line per ladder file that moved
15	#   mg_phases <microgpt-phase.md>
16	#                         one "component<TAB>phase" line per row of the microGPT phase table
17	#
18	# Source it from the tree's root, with FORTRESS_HOME set to that root, in the same Bash call that uses
19	# the functions, since each call starts a new shell:
20	#
21	#     source explorations/coordinator/tools/gate-functions.sh
22	#
23	# It defines the functions and runs nothing. The batch script's gate role
24	# (explorations/coordinator/climb-batch-workflow.js, steps 5 and 7) sources it, and so can any gate run
25	# by hand (the fortress-repo skill's gate.md). Until 2026-10-10 the functions were strings of the batch
26	# script, and the skill extracted them with node and awk (explorations/reviews/skills-agenda-audit.md,
27	# finding GA2).
28	
29	gate_summary () {
30	    local L="$1" O="$2" R="$FORTRESS_HOME/ProjectFortress/TEST-RESULTS" f
31	    {
32	      printf '#suite\ttests\tfailures\terrors\tskipped\n'
33	      for f in "$R"/fast-*/TEST-*.txt "$R"/system-*/TEST-*.txt "$R"/TEST-*SpecDataJUTest.txt ; do
34	        [ -f "$f" ] || continue
35	        awk -v track="$(case "$(basename "$(dirname "$f")")" in TEST-RESULTS) echo specdata ;; *) basename "$(dirname "$f")" ;; esac)" -F'[ ,:]+' '
36	          /^Testsuite:/ { n = split($2, p, "."); s = p[n] }
37	          /^Tests run:/ { print track "/" s "\t" $3 "\t" $5 "\t" $7 "\t" $9 ; exit }' "$f"
38	      done | sort
39	      for f in compileAll testFast testSystem testSpecData ; do
40	        [ -f "$L/$f.txt" ] && grep -h '^BUILD \|^Total time:' "$L/$f.txt" | sed "s|^|# $f: |"
41	      done
42	      bash explorations/compile-ladder/rung-flat-tower/machine.sh "${3:-gate}" | sed 's|^|# machine |'
43	    } > "$O"
44	}
45	
46	gate_compare () {
47	    awk -F'\t' '
48	      function key(s) { sub("^system-[0-9]+/", "system/", s) ; return s }
49	      FNR == NR { if ($0 !~ /^#/ && NF == 5) base[key($1)] += $2 ; next }
50	      $0 !~ /^#/ && NF == 5 {
51	          k = key($1) ; seen[k] = 1 ; cur[k] += $2
52	          if ($3 + 0 > 0 || $4 + 0 > 0)              { print "RED\t" $1 "\t" $3 " failures, " $4 " errors" ; bad++ }
53	          if ($2 + 0 == 0)                           { print "EMPTY\t" $1 ; bad++ }
54	      }
55	      END { for (k in cur) if ((k in base) && cur[k] < base[k]) { print "COUNT DOWN\t" k "\t" base[k] " -> " cur[k] ; bad++ }
56	            for (s in base) if (!(s in seen)) { print "SUITE GONE\t" s "\t" base[s] " -> absent" ; bad++ }
57	            if (bad) exit 1 }' "$1" "$2"
58	}
59	
60	last_landed_summary () {
61	    git -C "$FORTRESS_HOME" log --name-only --pretty=format: -- \
62	        'explorations/compile-ladder/gate-baseline/summary.txt' \
63	        'explorations/compile-ladder/climb-batch-*/gate/summary.txt' | grep -m1 'summary.txt$'
64	}
65	
66	ladder_filter () { sed -E 's/Operation took [0-9.]+ms/Operation took <time>ms/' "$1" ; }
67	
68	ladder_compare () {
69	    local B="$1" N="$2" key
70	    awk -F'\t' '
71	      function rank(p,   r) { r["parse"]=1; r["disambiguate"]=2; r["typecheck"]=3; r["codegen"]=4;
72	                              r["link"]=5; r["run"]=6; r["pass"]=7; return r[p] + 0 }
73	      FNR == NR { if (FNR > 1) b[$1 "/" $2] = $4 ; next }
74	      FNR > 1 {
75	          k = $1 "/" $2
76	          if (!(k in b))                  { print "NEW\t" k "\t" $4 ; next }
77	          if (rank($4) < rank(b[k]))      { print "DOWN\t" k "\t" b[k] " -> " $4 }
78	          else if (rank($4) > rank(b[k])) { print "UP\t" k "\t" b[k] " -> " $4 }
79	      }' "$B/ladder.tsv" "$N/ladder.tsv"
80	    tail -n +2 "$B/pass-list.txt" | cut -f1 | while IFS= read -r key ; do
81	        [ -n "$key" ] || continue
82	        if [ ! -f "$N/raw/$key.run" ] ; then printf 'MISSING\t%s\n' "$key" ; continue ; fi
83	        if ! diff -q <(ladder_filter "$B/raw/$key.run") <(ladder_filter "$N/raw/$key.run") >/dev/null ; then
84	            printf 'STDOUT\t%s\n' "$key"
85	            diff <(ladder_filter "$B/raw/$key.run") <(ladder_filter "$N/raw/$key.run") | sed 's/^/    /' | head -8
86	        fi
87	    done
88	}
89	
90	mg_phases () { awk -F'|' '/^\| *[0-9]+ *\| *`/ { gsub(/[` ]/, "", $3); gsub(/ /, "", $4); print $3 "\t" $4 }' "$1" ; }

  description: 'One batch of Fortress compile-ladder rungs in seeded worktrees: each rung done test first by its worker and checked by a skeptic that fixes what it finds, a judge only on a contested fix or a refusal; gathered onto main, reviewed beside one gate, landed and pushed; its revival-change material left in the batch record for the skill writer',
  phases: [
    { title: 'Disk', detail: 'df -P /home/user read before the scatter; under the floor of 1.5 G a rung and 4 G for the main tree, the run stops before any rung starts' },
    { title: 'Rung', detail: 'the rung done test first in its own seeded worktree, committed and pushed to its wip/ branch as it goes' },
    { title: 'Skeptic', detail: 'the rung checked by reading and by programs of its own on the old and new code; what it finds it fixes, test first, and it marks a fix contested when nothing on record settles it' },
    { title: 'Judge', detail: 'Opus for a first ruling, Fable for a second on the same rung or tree: only on a contested fix, a refusal, a worker that stopped, a blocking review or a red gate' },
    { title: 'Gather', detail: 'each approved rung applied to main in one commit with its record folded, the new ledger rows added through ledger.py, the rows it fixed closed' },
    { title: 'Review', detail: 'the merged diff, the skeptics\' fixes and the folded record read as a whole, once, beside the gate' },
    { title: 'Gate', detail: 'compileAll, the suites at four threads, testSpecData once a rung brings it, the atomic runs, the ladder regression, the checker count, and the distance stage beside them, reported and never red' },
    { title: 'Commit', detail: 'the gate\'s tables landed, the microGPT walk check run, the batch checked for skill text it should not have written, main pushed to its three branches in one atomic push, the worktrees removed; no push while a step that cannot be undone is unlifted' },
  ],
}

// Temporary, for the week of the Fable 5.2 launch offer (the curator's order of 2026-11-10): every agent runs
// on Fable, at medium effort where it ran on Opus; the disk check keeps its low effort, and a judge's second
----
// manifest fields; section 6, the intro of run 2) and the briefings of lists35.py; check35.js checks it.
// The record holds two runs: climb batch 35 (rungs R, W, S, O, A) and 35b (E, L, M).
// Climb batch 35b: rungs E, L, M, the manifest's order; none lands only with another.
// Per rung: id, slug, path, branch, expectedMinutes (the scatter's start order only),
// writesState, testIsStage, gateJoins (a gate step the rung brings), blurb (one line
// for the batch table), section (the rung's section of the record, read by every role
// on the rung), pointsToReport, briefing and reasons (the facts-extract.sh keys the
// worker reads first, each with its reason; of section 3's forks, the record's one
// key, "Forks the batch takes" whole, for every rung), checks (the sub-list the
// skeptic, a judge and a repair round read), expectedMoves (ladder moves declared,
// none here), and the optional landsOnlyWith, expectedCheckerCount and
// expectedCheckerCrash: no rung lands only with another (section 1's common fields),
// and none declares a checker count or a crash (the count is reported).
// No rung brings a gate step: every new or promoted test is in a gated folder.
// Every string here is ASCII: the record's sections hold no other character.
// No value is set at launch. The base and the base build are args.base and
// args.baseBuild. At most two agents run at once on this box, FIFO (FACTS.md, "The
// Workflow harness runs two agents at once on this box"); the scatter starts the
// longest expected worker first.
// ===========================================================================

const BATCH = '35b'
const BATCH_RECORD = 'explorations/coordinator/CLIMB-BATCH-35.md'
----
const SPEC_PDF = MAIN + '/tmp/gather/fortress-batch-' + BATCH + '.pdf'   // the gather's build of the specification, which the commit stage takes when no later commit changes Specification/
// A repair's build of the specification on the merged tree, kept as the gather keeps its own, which the commit stage
// takes when no commit after the repair's changes Specification/: climb batch 33b's review repair removed its build and
// kept no PDF, and the commit stage built the same text again (reviews/batch-33b-review.md, section 6 and process finding 6).
const repairPdf = (kind) => MAIN + '/tmp/repair-' + kind + '/fortress-batch-' + BATCH + '.pdf'

// The disk free on /home/user that the run needs before its scatter, in GiB: 1.5 a rung and 4 for the
// main tree. A rung worktree is seeded at about 206 MB (the skill's worktrees.md) and grows with its
// builds, its test runs and the old code's private caches: du -sh gave 0.28 to 1.1 G each in climb
// batch 27's agents. The main tree's stages write the gather's builds and demos, the gate's
// TEST-RESULTS and the ladder's two copies of the caches, and the specification's build. Climb batch
// 27 started its ten rungs without that margin: the allowance ran out (31 MB to 443 MB free through
// the batch), rungs S and T never started, and other stages skipped their measures (its RECORD.md,
// "Not landed"; PLAN.md item 68). The figures are the coordinator's of 2026-11-07, after that batch.
const DISK_FLOOR_G = { perRung: 1.5, mainTree: 4 }

// The scatter order: longest expected worker first. Manifest order is kept for the gather.
const SCATTER = RUNGS.slice().sort((a, b) => (b.expectedMinutes || 0) - (a.expectedMinutes || 0))

// ---------------------------------------------------------------------------
// The manifest, checked at load.

function recoverGate() {
  return [
    'You are in the main tree, ' + MAIN + '. The earlier attempt\'s logs are under ' + LOG_DIR + '/ and its outputs under ' + GATE_OUT + '/: ls -lt both. A log counts only if it is newer than the newest commit that touches a path outside explorations/ and .claude/ (git log -1 --format=%ci -- . ":(exclude)explorations" ":(exclude).claude").',
    bgCheck(MAIN),
    'A step whose log ends in EXIT=0 with BUILD SUCCESSFUL is done: do not run it again, and above all do not repeat step 2 once step 4 has finished, since its rm -rf ProjectFortress/TEST-RESULTS deletes the suites\' results. Step 3\'s copies stand only if both exist. The distance stage: when its log ends in EXIT= it finished; when not and a java DistanceMulti runs in ' + MAIN + ', it still runs; either way do not start it again. Only when its log has no EXIT= line and no such process runs, remove the log and start it again.',
    'Steps 5 to 9 write into summary.txt, step 5 anew and the later ones appending: continue at the first whose lines are not there; if one stopped partway, run again from step 5, so that no line lands twice (the distance stage itself is not run again for that, only its comparison).',
  ]
}
